select q.frase, r.n, r.title, r.fonte, r.sim, r.image_url
from q
cross join lateral (
  select row_number() over (order by ci.embedding <=> q.v) as n, ci.title, s.name as fonte,
         round((1 - (ci.embedding <=> q.v))::numeric, 4) as sim, ci.image_url
